            mapping[tuple(b)] = (2 * np.array([int(x) for x in np.binary_repr(i, 6)]) - np.array([1] * 6)).reshape(3, 2)
            mapping[tuple(b)] = mapping[tuple(b)][0] + 1j * mapping[tuple(b)][1]
        syms = np.array([mapping[(int(a), int(b), int(c), int(d), int(e), int(f))] for a, b, c, d, e, f in sixbits]) / np.sqrt(42)
    return syms, len(syms), np.log2(mod_order)
